<?php
namespace App\Http\Controllers;
use App\Models\{Person,SacramentalRecord}; use App\Services\SacramentalRecordValidator; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class RecordController extends Controller { private function shape(SacramentalRecord $r):array{$p=$r->person;return ['id'=>$r->id,'sacrament'=>$r->sacrament_type,'eventDate'=>(string)$r->event_date?->format('Y-m-d'),'book'=>$r->book_number,'page'=>$r->page_number,'line'=>$r->line_number,'minister'=>$r->minister_name,'sponsors'=>$r->sponsors,'marginNotes'=>$r->margin_notes,'firstName'=>$p->first_name,'middleName'=>$p->middle_name,'lastName'=>$p->last_name,'gender'=>$p->gender,'dob'=>$p->date_of_birth?->format('Y-m-d'),'fatherName'=>$p->father_name,'motherName'=>$p->mother_maiden_name,'spouse'=>$p->spouse_name];} public function index(Request $r){$q=$r->query('q','');$rows=SacramentalRecord::with('person')->whereHas('person',fn($x)=>$x->where('first_name','like',"%$q%")->orWhere('middle_name','like',"%$q%")->orWhere('last_name','like',"%$q%")->orWhere('date_of_birth','like',"%$q%"))->orderByDesc('event_date')->get();return response()->json(['data'=>$rows->map(fn($x)=>$this->shape($x))->values(),'meta'=>['total'=>$rows->count(),'page'=>1,'per_page'=>min(100,max(1,(int)$r->query('per_page',25)))]]);} public function show(SacramentalRecord $record){$record->load('person');return response()->json(['data'=>$this->shape($record)]);} public function store(Request $r,SacramentalRecordValidator $v){[$f,$e]=$v->validate($r->all());if($e)return response()->json(['error'=>'Validation failed','errors'=>$e],422);$record=DB::transaction(function()use($f,$r){$p=Person::firstOrCreate(['first_name'=>$f['first_name'],'last_name'=>$f['last_name'],'date_of_birth'=>$f['date_of_birth']?:null],$f);$rec=SacramentalRecord::create(['person_id'=>$p->id,'sacrament_type'=>$f['sacrament_type'],'event_date'=>$f['event_date'],'book_number'=>$f['book_number'],'page_number'=>$f['page_number'],'line_number'=>$f['line_number'],'minister_name'=>$f['minister_name']?:null,'sponsors'=>$f['sponsors']?:null,'margin_notes'=>$f['margin_notes']?:null,'created_by'=>$r->user()->id]);return $rec->load('person');});return response()->json(['data'=>$this->shape($record),'meta'=>['next_book_number'=>$f['book_number'],'next_line_number'=>(string)((int)$f['line_number']+1),'dedupe_match'=>false]],201);} }
